import{_ as o,a0 as l,w as d,s as r,ao as p,I as n,x as e,a1 as t,A as a}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const y=JSON.parse('{"title":"Git 系列（六）：如何搭建你自己的 Git 服務器 | LCTT x X-CMD","titleTemplate":false,"description":"Git 系列（六）：如何搭建你自己的 Git 服務器 | LCTT (201609) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Git 系列（六）：如何搭建你自己的 Git 服務器 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Git 系列（六）：如何搭建你自己的 Git 服務器 | LCTT (201609) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201609/20160809 How to build your own Git server","title":"Git 系列（六）：如何搭建你自己的 Git 服務器","tag":"201609","desc":""},"relativePath":"201609/20160809 How to build your own Git server.md","filePath":"[post].md"}'),h={name:"201609/20160809 How to build your own Git server.md"};function c(g,s,u,k,b,m){const i=l("Link");return d(),r("div",null,[s[24]||(s[24]=p('<h1 id="git-系列-六-如何搭建你自己的-git-服務器" tabindex="-1">Git 系列（六）：如何搭建你自己的 Git 服務器 <a class="header-anchor" href="#git-系列-六-如何搭建你自己的-git-服務器" aria-label="Permalink to “Git 系列（六）：如何搭建你自己的 Git 服務器”">​</a></h1><p><img src="https://opensource.com/sites/default/files/styles/image-full-size/public/images/business/bus-big-data.png?itok=sOQHDuID" alt=""></p><p>現在我們將要學習如何搭建 git 服務器，如何編寫自定義的 Git 鈎子來在特定的事件觸發相應的動作（例如通知），或者是發佈你的代碼到一個站點。</p><p>直到現在，我們主要討論的還是以一個使用者的身份與 Git 進行交互。這篇文章中我將討論 Git 的管理，並且設計一個靈活的 Git 框架。你可能會覺得這聽起來是 “高階 Git 技術” 或者 “只有狂熱粉才能閲讀”的一句委婉的説法，但是事實是這裏面的每個任務都不需要很深的知識或者其他特殊的訓練，就能基本理解 Git 的工作原理，有可能需要一丁點關於 Linux 的知識。</p><h3 id="共享-git-服務器" tabindex="-1">共享 Git 服務器 <a class="header-anchor" href="#共享-git-服務器" aria-label="Permalink to “共享 Git 服務器”">​</a></h3><p>創建你自己的共享 Git 服務器意外地簡單，而且在很多情況下，遇到的這點麻煩是完全值得的。不僅僅是因為它保證你有權限查看自己的代碼，它還可以通過擴展為 Git 的使用敞開了一扇大門，例如個人 Git 鈎子、無限制的數據存儲、和持續集成與分發（CI &amp; CD）。</p><p>如果你知道如何使用 Git 和 SSH，那麼你已經知道怎麼創建一個 Git 服務器了。Git 的設計方式，就是讓你在創建或者 clone 一個倉庫的時候，就完成了一半服務器的搭建。然後允許用 SSH 訪問倉庫，而且任何有權限訪問的人都可以使用你的倉庫作為 clone 的新倉庫的基礎。</p><p>但是，這是一個小的點對點環境（ad-hoc）。按照一些方案你可以創建一些帶有同樣的功能的設計優良的 Git 服務器，同時有更好的拓展性。</p><p>首要之事：確認你的用户們，現在的用户以及之後的用户都要考慮。如果你是唯一的用户那麼沒有任何改動的必要。但是如果你試圖邀請其他的代碼貢獻者使用，那麼你應該允許一個專門的分享系統用户給你的開發者們。</p>',9)),n("p",null,[s[1]||(s[1]=e("假定你有一個可用的服務器（如果沒有，這不成問題，Git 會幫忙解決，CentOS 的 ",-1)),t(i,{href:"https://wiki.centos.org/SpecialInterestGroup/AltArch/Arm32/RaspberryPi3"},{default:a(()=>[...s[0]||(s[0]=[e("樹莓派 3",-1)])]),_:1}),s[2]||(s[2]=e(" 是個不錯的開始），然後第一步就是隻允許使用 SSH 密鑰認證的 SSH 登錄。這比使用密碼登錄安全得多，因為這可以免於暴力破解，也可以通過直接刪除用户密鑰而禁用用户。",-1))]),s[25]||(s[25]=p(`<p>一旦你啓用了 SSH 密鑰認證，創建 <code>gituser</code> 用户。這是給你的所有授權的用户們的公共用户：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ su -c &#39;adduser gituser&#39;</span></span></code></pre></div><p>然後切換到剛創建的 <code>gituser</code> 用户，創建一個 <code>~/.ssh</code> 的框架，並設置好合適的權限。這很重要，如果權限設置得太開放會使自己所保護的 SSH 沒有意義。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ su - gituser</span></span>
<span class="line"><span>$ mkdir .ssh &amp;&amp; chmod 700 .ssh</span></span>
<span class="line"><span>$ touch .ssh/authorized_keys</span></span>
<span class="line"><span>$ chmod 600 .ssh/authorized_keys</span></span></code></pre></div><p><code>authorized_keys</code> 文件裏包含所有你的開發者們的 SSH 公鑰，你開放權限允許他們可以在你的 Git 項目上工作。他們必須創建他們自己的 SSH 密鑰對然後把他們的公鑰給你。複製公鑰到 gituser 用户下的 <code>authorized_keys</code> 文件中。例如，為一個叫 Bob 的開發者，執行以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cat ~/path/to/id_rsa.bob.pub &gt;&gt; /home/gituser/.ssh/authorized_keys</span></span></code></pre></div><p>只要開發者 Bob 有私鑰並且把相對應的公鑰給你，Bob 就可以用 <code>gituser</code> 用户訪問服務器。</p><p>但是，你並不是想讓你的開發者們能使用服務器，即使只是以 <code>gituser</code> 的身份訪問。你只是想給他們訪問 Git 倉庫的權限。因為這個特殊的原因，Git 提供了一個限制的 shell，準確的説是 <code>git-shell</code>。以 root 身份執行以下命令，把 <code>git-shell</code> 添加到你的系統中，然後設置成 <code>gituser</code> 用户的默認 shell。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># grep git-shell /etc/shells || su -c &quot;echo \`which git-shell\` &gt;&gt; /etc/shells&quot;</span></span>
<span class="line"><span># su -c &#39;usermod -s git-shell gituser&#39;</span></span></code></pre></div><p>現在 <code>gituser</code> 用户只能使用 SSH 來 push 或者 pull Git 倉庫，並且無法使用任何一個可以登錄的 shell。你應該把你自己添加到和 <code>gituser</code> 一樣的組中，在我們的樣例服務器中這個組的名字也是 <code>gituser</code>。</p><p>舉個例子：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># usermod -a -G gituser seth</span></span></code></pre></div><p>僅剩下的一步就是創建一個 Git 倉庫。因為沒有人能在服務器上直接與 Git 交互（也就是説，你之後不能 SSH 到服務器然後直接操作這個倉庫），所以創建一個空的倉庫 。如果你想使用這個放在服務器上的倉庫來完成工作，你可以從它的所在處 <code>clone</code> 下來，然後在你的 home 目錄下進行工作。</p><p>嚴格地講，你不是必須創建這個空的倉庫；它和一個正常的倉庫一樣工作。但是，一個空的倉庫沒有工作分支（working tree） （也就是説，使用 <code>checkout</code> 並沒有任何分支顯示）。這很重要，因為不允許遠程使用者們 <code>push</code> 到一個有效的分支上（如果你正在 <code>dev</code> 分支工作然後突然有人把一些變更 <code>push</code> 到你的工作分支，你會有怎麼樣的感受？）。因為一個空的倉庫可以沒有有效的分支，所以這不會成為一個問題。</p><p>你可以把這個倉庫放到任何你想放的地方，只要你想要放開權限給用户和用户組，讓他們可以在倉庫下工作。千萬不要保存目錄到比如説一個用户的 home 目錄下，因為那裏有嚴格的權限限制。保存到一個常規的共享地址，例如 <code>/opt</code> 或者 <code>/usr/local/share</code>。</p><p>以 root 身份創建一個空的倉庫：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># git init --bare /opt/jupiter.git</span></span>
<span class="line"><span># chown -R gituser:gituser /opt/jupiter.git</span></span>
<span class="line"><span># chmod -R 770 /opt/jupiter.git</span></span></code></pre></div><p>現在任何一個用户，只要他被認證為 <code>gituser</code> 或者在 <code>gituser</code> 組中，就可以從 jupiter.git 庫中讀取或者寫入。在本地機器嘗試以下操作：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git clone gituser@example.com:/opt/jupiter.git jupiter.clone</span></span>
<span class="line"><span>Cloning into &#39;jupiter.clone&#39;...</span></span>
<span class="line"><span>Warning: you appear to have cloned an empty repository.</span></span></code></pre></div><p>謹記：開發者們<strong>一定</strong>要把他們的 SSH 公鑰加入到 <code>gituser</code> 用户下的 <code>authorized_keys</code> 文件裏，或者説，如果他們有服務器上的用户（如果你給了他們用户），那麼他們的用户必須屬於 <code>gituser</code> 用户組。</p><h3 id="git-鈎子" tabindex="-1">Git 鈎子 <a class="header-anchor" href="#git-鈎子" aria-label="Permalink to “Git 鈎子”">​</a></h3><p>運行你自己的 Git 服務器最讚的一件事之一就是可以使用 Git 鈎子。Git 託管服務有時提供一個鈎子類的接口，但是他們並不會給你真正的 Git 鈎子來讓你訪問文件系統。Git 鈎子是一個腳本，它將在一個 Git 過程的某些點運行；鈎子可以運行在當一個倉庫即將接收一個 commit 時、或者接受一個 commit 之後，或者即將接收一次 push 時，或者一次 push 之後等等。</p><p>這是一個簡單的系統：任何放在 <code>.git/hooks</code> 目錄下的腳本、使用標準的命名體系，就可按設計好的時間運行。一個腳本是否應該被運行取決於它的名字； <code>pre-push</code> 腳本在 <code>push</code> 之前運行，<code>post-receive</code> 腳本在接受 <code>commit</code> 之後運行等等。這或多或少的可以從名字上看出來。</p><p>腳本可以用任何語言寫；如果在你的系統上有可以執行的腳本語言，例如輸出 ‘hello world’ ，那麼你就可以這個語言來寫 Git 鈎子腳本。Git 默認帶了一些例子，但是並不有啓用。</p><p>想要動手試一個？這很簡單。如果你沒有現成的 Git 倉庫，首先創建一個 Git 倉庫：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ mkdir jupiter</span></span>
<span class="line"><span>$ cd jupiter</span></span>
<span class="line"><span>$ git init .</span></span></code></pre></div><p>然後寫一個 “hello world” 的 Git 鈎子。因為我為了支持老舊系統而使用 tsch，所以我仍然用它作為我的腳本語言，你可以自由的使用自己喜歡的語言（Bash，Python，Ruby，Perl，Rust，Swift，Go）：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ echo &quot;#\\!/bin/tcsh&quot; &gt; .git/hooks/post-commit</span></span>
<span class="line"><span>$ echo &quot;echo &#39;POST-COMMIT SCRIPT TRIGGERED&#39;&quot; &gt;&gt; ~/jupiter/.git/hooks/post-commit</span></span>
<span class="line"><span>$ chmod +x ~/jupiter/.git/hooks/post-commit</span></span></code></pre></div><p>現在測試它的輸出：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ echo &quot;hello world&quot; &gt; foo.txt</span></span>
<span class="line"><span>$ git add foo.txt</span></span>
<span class="line"><span>$ git commit -m &#39;first commit&#39;</span></span>
<span class="line"><span>! POST-COMMIT SCRIPT TRIGGERED</span></span>
<span class="line"><span>[master (root-commit) c8678e0] first commit</span></span>
<span class="line"><span>1 file changed, 1 insertion(+)</span></span>
<span class="line"><span>create mode 100644 foo.txt</span></span></code></pre></div><p>現在你已經實現了：你的第一個有功能的 Git 鈎子。</p><h3 id="有名的-push-to-web-鈎子" tabindex="-1">有名的 push-to-web 鈎子 <a class="header-anchor" href="#有名的-push-to-web-鈎子" aria-label="Permalink to “有名的 push-to-web 鈎子”">​</a></h3><p>Git 鈎子最流行的用法就是自動 <code>push</code> 更改的代碼到一個正在使用中的產品級 Web 服務器目錄下。這是擺脱 FTP 的很好的方式，對於正在使用的產品保留完整的版本控制，整合並自動化內容的發佈。</p>`,33)),n("p",null,[s[4]||(s[4]=e("如果操作正確，網站發佈工作會像以前一樣很好的完成，而且在某種程度上，很精準。Git 真的好棒。我不知道誰最初想到這個主意，但是我是從 Emacs 和 Git 方面的專家，IBM 的 Bill von Hagen 那裏第一次聽到它的。他的文章包含關於這個過程的權威介紹：",-1)),t(i,{href:"http://www.ibm.com/developerworks/library/wa-git/"},{default:a(()=>[...s[3]||(s[3]=[e("Git 改變了分佈式網頁開發的遊戲規則",-1)])]),_:1}),s[5]||(s[5]=e("。",-1))]),s[26]||(s[26]=p(`<h3 id="git-變量" tabindex="-1">Git 變量 <a class="header-anchor" href="#git-變量" aria-label="Permalink to “Git 變量”">​</a></h3><p>每一個 Git 鈎子都有一系列不同的變量對應觸發鈎子的不同 Git 行為。你需不需要這些變量，主要取決於你寫的程序。如果你只是需要一個當某人 push 代碼時候的通用郵件通知，那麼你就不需要什麼特殊的東西，甚至也不需要編寫額外的腳本，因為已經有現成的適合你的樣例腳本。如果你想在郵件裏查看 commit 信息和 commit 的作者，那麼你的腳本就會變得相對麻煩些。</p><p>Git 鈎子並不是被用户直接執行，所以要弄清楚如何收集可能會混淆的重要信息。事實上，Git 鈎子腳本類似於其他的腳本，像 BASH、Python、C++ 等等一樣從標準輸入讀取參數。不同的是，我們不會給它提供這個輸入，所以，你在使用的時候，需要知道可能的輸入參數。</p><p>在寫 Git 鈎子之前，看一下 Git 在你的項目目錄下 <code>.git/hooks</code> 目錄中提供的一些例子。舉個例子，在這個 <code>pre-push.sample</code> 文件裏，註釋部分説明了如下內容：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># $1 -- 即將 push 的遠程倉庫的名字</span></span>
<span class="line"><span># $2 -- 即將 push 的遠程倉庫的 URL</span></span>
<span class="line"><span># 如果 push 的時候，並沒有一個命名的遠程倉庫，那麼這兩個參數將會一樣。</span></span>
<span class="line"><span>#</span></span>
<span class="line"><span># 提交的信息將以下列形式按行發送給標準輸入</span></span>
<span class="line"><span># &lt;local ref&gt; &lt;local sha1&gt; &lt;remote ref&gt; &lt;remote sha1&gt;</span></span></code></pre></div>`,5)),n("p",null,[s[7]||(s[7]=e("並不是所有的例子都是這麼清晰，而且關於鈎子獲取變量的文檔依舊缺乏（除非你去讀 Git 的源碼）。但是，如果你有疑問，你可以從線上",-1)),t(i,{href:"https://www.analysisandsolutions.com/code/git-hooks-summary-cheat-sheet.htm"},{default:a(()=>[...s[6]||(s[6]=[e("其他用户的嘗試中",-1)])]),_:1}),s[8]||(s[8]=e("學習，或者你只是寫一些基本的腳本，比如 ",-1)),s[9]||(s[9]=n("code",null,"echo $1, $2, $3",-1)),s[10]||(s[10]=e(" 等等。",-1))]),s[27]||(s[27]=p(`<h3 id="分支檢測示例" tabindex="-1">分支檢測示例 <a class="header-anchor" href="#分支檢測示例" aria-label="Permalink to “分支檢測示例”">​</a></h3><p>我發現，對於生產環境來説有一個共同的需求，就是需要一個只有在特定分支被修改之後，才會觸發事件的鈎子。以下就是如何跟蹤分支的示例。</p><p>首先，Git 鈎子本身是不受版本控制的。 Git 並不會跟蹤它自己的鈎子，因為對於鈎子來説，它是 Git 的一部分，而不是你倉庫的一部分。所以，Git 鈎子可以監控你的 Git 服務器上的一個空倉庫的 commit 記錄和 push 記錄，而不是你本地倉庫的一部分。</p><p>我們來寫一個 <code>post-receive</code>（也就是説，在 <code>commit</code> 被接受之後觸發）鈎子。第一步就是需要確定分支名：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>#!/bin/tcsh</span></span>
<span class="line"><span></span></span>
<span class="line"><span>foreach arg ( $&lt; )</span></span>
<span class="line"><span>  set argv = ( $arg )</span></span>
<span class="line"><span>  set refname = $1</span></span>
<span class="line"><span>end</span></span></code></pre></div><p>這個 for 循環用來讀入第一個參數 <code>$1</code> ，然後循環用第二個參數 <code>$2</code> 去覆蓋它，然後用第三個參數 <code>$3</code> 再這樣。在 Bash 中有一個更好的方法，使用 <code>read</code> 命令，並且把值放入數組裏。但是，這裏是 tcsh，並且變量的順序可以預測的，所以，這個方法也是可行的。</p><p>當我們有了 commit 記錄的 <code>refname</code>，我們就能使用 Git 去找到這個分支的供人看的名字：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>set branch = \`git rev-parse --symbolic --abbrev-ref $refname\`</span></span>
<span class="line"><span>echo $branch #DEBUG</span></span></code></pre></div><p>然後把這個分支名和我們想要觸發的事件的分支名關鍵字進行比較：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>if ( &quot;$branch&quot; == &quot;master&quot; ) then</span></span>
<span class="line"><span>  echo &quot;Branch detected: master&quot;</span></span>
<span class="line"><span>  git \\</span></span>
<span class="line"><span>    --work-tree=/path/to/where/you/want/to/copy/stuff/to \\</span></span>
<span class="line"><span>    checkout -f $branch || echo &quot;master fail&quot;</span></span>
<span class="line"><span>else if ( &quot;$branch&quot; == &quot;dev&quot; ) then</span></span>
<span class="line"><span>  echo &quot;Branch detected: dev&quot;</span></span>
<span class="line"><span>  Git \\</span></span>
<span class="line"><span>    --work-tree=/path/to/where/you/want/to/copy/stuff/to \\</span></span>
<span class="line"><span>    checkout -f $branch || echo &quot;dev fail&quot;</span></span>
<span class="line"><span>  else</span></span>
<span class="line"><span>    echo &quot;Your push was successful.&quot;</span></span>
<span class="line"><span>    echo &quot;Private branch detected. No action triggered.&quot;</span></span>
<span class="line"><span>endif</span></span></code></pre></div><p>給這個腳本分配可執行權限：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ chmod +x ~/jupiter/.git/hooks/post-receive</span></span></code></pre></div><p>現在，當一個用户提交到服務器的 master 分支，那些代碼就會被複制到一個生產環境的目錄，提交到 dev 分支則會被複制到另外的地方，其他分支將不會觸發這些操作。</p><p>同時，創造一個 <code>pre-commit</code> 腳本也很簡單。比如，判斷一個用户是否在他們不該 <code>push</code> 的分支上 <code>push</code> 代碼，或者對 commit 信息進行解析等等。</p><p>Git 鈎子也可以變得複雜，而且它們因為 Git 的工作流的抽象層次不同而變得難以理解，但是它們確實是一個強大的系統，讓你能夠在你的 Git 基礎設施上針對所有的行為進行對應的操作。如果你是一個 Git 重度用户，或者一個全職 Git 管理員，那麼 Git 鈎子是值得學習的，只有當你熟悉這個過程，你才能真正掌握它。</p><p>在我們這個系列下一篇也是最後一篇文章中，我們將會學習如何使用 Git 來管理非文本的二進制數據，比如音頻和圖片。</p><hr>`,17)),n("p",null,[s[12]||(s[12]=e("via: ",-1)),t(i,{href:"https://opensource.com/life/16/8/how-construct-your-own-git-server-part-6"},{default:a(()=>[...s[11]||(s[11]=[e("https://opensource.com/life/16/8/how-construct-your-own-git-server-part-6",-1)])]),_:1})]),n("p",null,[s[16]||(s[16]=e("作者：",-1)),t(i,{href:"https://opensource.com/users/seth"},{default:a(()=>[...s[13]||(s[13]=[e("Seth Kenlon",-1)])]),_:1}),s[17]||(s[17]=e(" 譯者：",-1)),t(i,{href:"https://github.com/maywanting"},{default:a(()=>[...s[14]||(s[14]=[e("maywanting",-1)])]),_:1}),s[18]||(s[18]=e(" 校對：",-1)),t(i,{href:"https://github.com/wxy"},{default:a(()=>[...s[15]||(s[15]=[e("wxy",-1)])]),_:1})]),n("p",null,[s[21]||(s[21]=e("本文由 ",-1)),t(i,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...s[19]||(s[19]=[e("LCTT",-1)])]),_:1}),s[22]||(s[22]=e(" 原創編譯，",-1)),t(i,{href:"https://linux.cn/"},{default:a(()=>[...s[20]||(s[20]=[e("Linux中國",-1)])]),_:1}),s[23]||(s[23]=e(" 榮譽推出",-1))])])}const C=o(h,[["render",c]]);export{y as __pageData,C as default};
